# Run this once barbara.anders@gmail.com has clicked the SES verification link
$msgJson = @{
    Subject = @{ Data = "Your BetBudAI subscription has been cancelled"; Charset = "UTF-8" }
    Body = @{
        Text = @{ Data = "Hi Barbara,`n`nYour BetBudAI Premium subscription has been cancelled as requested.`n`nPlan: Premium (EUR 29/month)`nAccess until: 12 June 2026`nStatus: Cancellation confirmed - no further charges`n`nYou still have full Premium access to all daily picks until 12 June 2026. After that your account will revert to the free tier.`n`nIf you change your mind, visit https://www.betbudai.com to re-subscribe.`n`nBest regards,`nThe BetBudAI Team"; Charset = "UTF-8" }
        Html = @{ Data = "<!DOCTYPE html><html><head><meta charset=utf-8><style>body{font-family:-apple-system,BlinkMacSystemFont,sans-serif;background:#f8fafc;margin:0;padding:0}.wrap{max-width:560px;margin:40px auto;background:#fff;border-radius:12px;overflow:hidden;box-shadow:0 2px 12px rgba(0,0,0,.08)}.hdr{background:linear-gradient(135deg,#0f172a,#1e3a5f);padding:32px 40px}.hdr h1{color:#fff;font-size:22px;margin:0;font-weight:700}.hdr p{color:#94a3b8;font-size:13px;margin:6px 0 0}.bdy{padding:36px 40px;color:#334155;line-height:1.7}.bdy h2{font-size:18px;color:#0f172a;margin:0 0 16px}.box{background:#f1f5f9;border-radius:8px;padding:20px 24px;margin:24px 0}.box p{margin:6px 0;font-size:14px;color:#475569}.btn{text-align:center;margin:28px 0}.btn a{background:#16a34a;color:#fff;text-decoration:none;padding:12px 28px;border-radius:8px;font-weight:600;font-size:15px;display:inline-block}.ftr{background:#f8fafc;padding:20px 40px;text-align:center;font-size:12px;color:#94a3b8}</style></head><body><div class=wrap><div class=hdr><h1>BetBudAI</h1><p>Subscription Update</p></div><div class=bdy><h2>Your subscription has been cancelled</h2><p>Hi Barbara,</p><p>We can confirm your BetBudAI Premium subscription has been cancelled as requested.</p><div class=box><p><strong>Plan:</strong> Premium (&euro;29/month)</p><p><strong>Access until:</strong> 12 June 2026</p><p><strong>Status:</strong> Cancellation confirmed &mdash; no further charges</p></div><p>You still have full Premium access to all daily picks and analysis until <strong>12 June 2026</strong>. After that your account will automatically revert to the free tier.</p><p>We're sorry to see you go. If you change your mind, you can re-subscribe at any time from the BetBudAI website.</p><div class=btn><a href=https://www.betbudai.com>Visit BetBudAI</a></div><p>If you have any questions, just reply to this email.</p><p>Best regards,<br><strong>The BetBudAI Team</strong></p></div><div class=ftr>BetBudAI &bull; You are receiving this because you had an active subscription.</div></div></body></html>"; Charset = "UTF-8" }
    }
} | ConvertTo-Json -Depth 5 -Compress

$msgJson | Out-File "$env:TEMP\barbara_cancel.json" -Encoding utf8

aws ses send-email --region eu-west-1 --from "charles.mccarthy@gmail.com" --to "barbara.anders@gmail.com" --message "file://$env:TEMP\barbara_cancel.json"
